    &lt;ModuleId&gt;997&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT \n    p.*,\n    s.Nume,\n    br.DenumireBeneficiar,\n    br.DenumireRata,\n    sca.Badge \nFROM app.Poprire p\n\nJOIN app.Salariat s \n    ON s.Marca = p.Marca \n    AND s.Anul = p.Anul \n    AND s.Luna = p.Luna \n    AND s.CodSucursala = p.CodSucursala\n    \nLEFT JOIN app.NomBeneficiarRetinere br \n    ON br.CodBeneficiar = p.CodBeneficiar\n    AND br.CodSucursala = p.CodSucursala\n    AND br.Judet = p.Judet\n    -- dacă vrei strict TipRataOld = 4:\n    AND br.TipRataOld = 6\nLEFT JOIN app.StatusCalcul sca\n  ON ISNULL(p.Status, 1) = sca.Id \n\nWHERE\np.CodSucursala = @CodSucursala AND p.Anul = @Anul AND p.Luna = @Luna\nORDER BY p.Marca desc,p.NumarCurent&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;Id&quot;,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot